scwin.vScrenID = "ULDSTF05975.xml";
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜
scwin.fr_SecuGrpId = "ST";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.nColCnt = 0;
scwin.vInValidCol4 = 0; // 법인등록번호
scwin.vInValidCol7 = 0; // 지정일 
scwin.vMsg = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_IsurCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_IsurNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].COM_NM);
};
scwin.fn_GetParIsur2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_IsurCd2); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_IsurNm2); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur2 = function(arrPar) {
    txb_IsurCd2.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm2.setValue(arrPar[0].COM_NM);
};
scwin.fn_GetParIsur3 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_IsurCd3); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_IsurNm3); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur3 = function(arrPar) {
    txb_IsurCd3.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm3.setValue(arrPar[0].COM_NM);
};

/*
	초기화 선언
*/
scwin.fn_init = function() {
    //TAB 1	
    MaxTab_01.setSelectedTabIndex(1);

    // TAB 2
    scwin.fn_setComboComTp(dts_ComTp);
    cmb_COM_TP.setSelectedIndex(0);
    edt_SDATE.setValue("19000101"); // 일주일전 날짜 	cGetMinusDate2(vCurDate, 365*2); 
    edt_EDATE.setValue(scwin.vCurDate); // 현재날짜	
    // TAB 3
    cmb_COM_TP3.setSelectedIndex(0);

    // Common Setting		
    scwin.fn_setBaseDate();

    // TAB 1 
    $c.stf.setObjectValue(edt_Date, dts_BasDate.getCellData(1, "BAS_DD"));
    // TAB 3날
    $c.stf.setObjectValue(edt_Date3, dts_BasDate.getCellData(1, "BAS_DD"));
};
scwin.fn_setBaseDate = function() {
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=lstVentBzRstBaseDate";
    url += "&inputMessageId=KOSDAQ_VENTBZ_STAT_INOUT&outputMessageId=KOSDAQ_VENTBZ_STAT_INOUT";
    url += "&BAS_DD=" + $c.stf.getObjectValue(edt_Date);
    dts_BasDate.DataID = encodeURI(url);
    dts_BasDate.reset();
};
scwin.fn_setComboComTp = function(dts_Cod) {
    var arrCid = [{
        cid: "SME_EMS_TP_CD",
        cnm: "cmb_COM_TP"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SME_EMS_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        strCbd = "(null)^전체";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_list_sync = function() {
    /*
    	코스닥상장 벤처 기업 현황
    */
    $c.stf.setObjectValue(txb_Msg, '');
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listVentBzStat";
    url += "&inputMessageId=KOSDAQ_VENTBZ_STAT_INOUT&outputMessageId=KOSDAQ_VENTBZ_STAT_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_IsurCd);
    url += "&BAS_DD=" + $c.stf.getObjectValue(edt_Date);
    dts_List1.DataID = encodeURI(url);
    dts_List1.reset();
    $c.cm.ShowWin(grd_List1);
};
scwin.fn_list_predate_diff = function() {
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listDiffVentBzAndSmeEmsStat";
    url += "&inputMessageId=KOSDAQ_VENTBZ_SME_EMS_TP_STAT_INOUT&outputMessageId=KOSDAQ_VENTBZ_SME_EMS_TP_STAT_INOUT";
    url += "&BAS_DD=" + $c.stf.getObjectValue(edt_Date);
    dts_PreDiff.DataID = encodeURI(url);
    dts_PreDiff.reset();
    var diffCntRatio = Math.round((dts_PreDiff.getCellData(1, "BAS_DD_CNT") - dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT")) / dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT") * 100);
    var msg = '* 마감 시 전일 ' + dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT") + '건 대비 ' + dts_PreDiff.getCellData(1, "BAS_DD_CNT") + '건 ' + diffCntRatio + '% 차이 발행합니다.';
    if (dts_PreDiff.getCellData(1, "PRE_BAS_DD_CNT") != 0 && dts_PreDiff.getCellData(1, "BAS_DD_CNT") != 0 && Math.abs(diffCntRatio) >= 10) {
        $c.stf.setObjectValue(txb_Msg, msg);
        $c.win.alert(msg);
        return false;
    }
    return true;
};
scwin.fn_list_sync2 = function() {
    /*
    	중소.중견기업 현황
    */
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listSmeEmsStat";
    url += "&inputMessageId=KOSDAQ_SME_EMS_TP_STAT_INOUT&outputMessageId=KOSDAQ_SME_EMS_TP_STAT_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_IsurCd2);
    url += "&SME_EMS_TP=" + $c.stf.getObjectValue(cmb_COM_TP);
    url += "&DATE_DIV=" + $c.stf.getObjectValue(rdo_DATE_TYP);
    url += "&STRT_DD=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&END_DD=" + $c.stf.getObjectValue(edt_EDATE);
    dts_List2.DataID = encodeURI(url);
    dts_List2.reset();
    $c.cm.ShowWin(grd_List2);
    scwin.nColCnt = 1;
};
scwin.fn_list_sync3 = function() {
    /*
    	종합화면
    */
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listVentBzAndSmeEmsStat";
    url += "&inputMessageId=KOSDAQ_VENTBZ_SME_EMS_TP_STAT_INOUT&outputMessageId=KOSDAQ_VENTBZ_SME_EMS_TP_STAT_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_IsurCd3);
    url += "&SME_EMS_TP_NM=" + $c.stf.getObjectValue(cmb_COM_TP3);
    url += "&BAS_DD=" + $c.stf.getObjectValue(edt_Date3);
    dts_List3.DataID = encodeURI(url);
    dts_List3.reset();
    $c.cm.ShowWin(grd_List3);
};


/*
	일괄등록
*/
scwin.fn_input = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF05976", "/lstproc/ULDSTF05976.gfm", "코스닥상장 벤처기업 입력", 300, 200, 980, 645, "window");
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};
scwin.fn_revw = function() {
    var vErrMsg = "";
    var vErrCnt = 0;
    if ($c.stf.getObjectValue(edt_Date) == "") {
        $c.win.alert("[일자]를 입력하세요.");
        edt_Date.focus();
        return;
    }
    scwin.fn_list_predate_diff();
    var res = window.confirm("[마감] 처리하겠습니까?");
    if (res) {
        scwin.fn_trs_revw('Y');
    }
};
scwin.fn_ReCls = function() {
    res = window.confirm("[재마감] 처리하겠습니까?");
    if (res) {
        scwin.fn_trs_revw('N');
        scwin.fn_list_sync();
    }
};
scwin.fn_trs_revw = function(clsYn) {
    dts_Cls.removeAll();
    //dts_Cls.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Cls.insertRow();
    dts_Cls.setCellData(1, "BAS_DD", $c.stf.getObjectValue(edt_Date));
    dts_Cls.setCellData(1, "VENTBZ_YN", clsYn);
    dts_Cls.setCellData(1, "CONFRMR_EMP_NO", js_emp_no);
    trs_Save.Action = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=revwVentBzStat";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Cls)";
    trs_Save.Post();
};
scwin.fn_isValidCheck = function() {
    scwin.vInValidCol4 = 0;
    scwin.vInValidCol7 = 0;
    for (var j = 1; j < dts_List1.getTotalRow(); j++) {
        if (dts_List1.getCellData(j, "VALID_ISUR_CD") == "N") {
            scwin.vInValidCol4 = j;
            scwin.vMsg = j + "번 '" + dts_List1.getCellData(j, "COM_NM") + "' 종목코드 또는 법인등록번호가 유효하지 않습니다.\n\n";
            return false;
        }
        if (dts_List1.getCellData(j, "VALID_DESIGN_DD") == "N") {
            scwin.vInValidCol7 = j;
            scwin.vMsg = j + "번 '" + dts_List1.getCellData(j, "COM_NM") + "' 벤처 지정일이 해제 예정일보다 이후 입니다.\n\n";
            return false;
        }
        if (scwin.fn_isValidDate(dts_List1.getCellData(j, "VENTBZ_DESIGN_DD")) == false ||
            scwin.fn_isValidDate(dts_List1.getCellData(j, "VENTBZ_RELEAS_SCHDL_DD")) == false ||
            scwin.fn_isValidDate(dts_List1.getCellData(j, "VENTBZ_RELEAS_DD")) == false) {
            scwin.vInValidCol7 = j;
            scwin.vMsg = j + "번 '" + dts_List1.getCellData(j, "COM_NM") + "' 벤처 지정(예정/해제) 날짜가 유효하지 않습니다.\n\n";
            return false;
        }
    }
    scwin.vMsg = '';
    return true;
};
scwin.fn_isValidDate = function(ymd) {
    var year = ymd.substring(0, 4);
    var month = ymd.substring(4, 6);
    var day = ymd.substring(6, 8);
    var d = new Date(year, month - 1, day);
    if (d.getFullYear() == year && $c.ut.lpad((d.getMonth() + 1), 2, '0') == month && $c.ut.lpad(d.getDate(), 2, '0') == day) {
        return true;
    }
    return false;
};
scwin.dts_List1_OnLoadError = function() {
    $c.cm.CloseWin(0, grd_List1);
    $c.stf.alert_error(dts_List1);
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List1);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (scwin.fn_isValidCheck() == true) {
        scwin.fn_list_predate_diff();
    } else {
        $c.stf.setObjectValue(txb_Msg, scwin.vMsg);
        $c.win.alert(scwin.vMsg);
    }
};
scwin.dts_List2_OnLoadError = function() {
    $c.cm.CloseWin(0, grd_List2);
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
