scwin.dts_BasDate_OnLoadCompleted = function(rowcount) {

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_init();
    var url = frame.srcUrl;
    var arr = url.split("?");
    if (arr.length > 1) {
        MaxTab_01.setSelectedTabIndex(2);
    }
};
scwin.btn_excel_onclick = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List1, "코스닥상장 벤처기업 현황", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List2, "중소ㆍ중견기업 확인 현황", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List3, "종합화면", "", "8");
    }
};
scwin.img_Date3_onclick = function() {
    popUpCalendar2(edt_Date3);
};
scwin.btn_IsuCdSearch3_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur3;
    scwin.fn_SetPar = fn_SetParIsur3;
