    scwin.fn_SetPar = fn_SetParIsur2;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.grd_List1_OnUserColor = function(row, eventId) {
    var colorName = "#FF40D0";
    if (row == scwin.vInValidCol4) {
        if (eventId == "acolor4" || eventId == "acolor5") {
            return colorName;
        } else {
            if (row % 2 == 0) return "#f2f5f9";

            else return "#ffffff";
        }
    }
    if (row == scwin.vInValidCol7) {
        if (eventId == "acolor7" || eventId == "acolor8" || eventId == "acolor9") {
            return colorName;
        } else {
            if (row % 2 == 0) return "#f2f5f9";

            else return "#ffffff";
        }
    }
    if (row % 2 == 0) return "#f2f5f9";

    else return "#ffffff";
};
scwin.grd_List2_OnUserColor = function(row, eventId) {
    var colorName = "#77FF88"; //11FF00";
    if (scwin.nColCnt > 0) {
        if (eventId == "acolor7") {
            if (dts_List2.getCellData(row, "DISCLS_COM_ABBRV") != dts_List2.getCellData(row, "COM_ABBRV") && dts_List2.getCellData(row, "COM_ABBRV") != "") {
                return colorName; // 연두색
            } else {
                if (row % 2 == 0) return "#f2f5f9";

                else return "#ffffff";
            }
        }
    }
    if (row % 2 == 0) return "#f2f5f9";

    else return "#ffffff";
};
scwin.txb_IsurCd_onblur = function() {
    if (txb_IsurCd.getValue() == "") {
        txb_IsurNm.setValue("");
    }
};
scwin.txb_IsurCd2_onblur = function() {
    if (txb_IsurCd2.getValue() == "") {
